"""Usage: run.py BASE OUTFILE  -- fetch every request in the probe set as admin, bob, anon."""
import json
import sys
import urllib.error
import urllib.request
from concurrent.futures import ThreadPoolExecutor

base, outfile = sys.argv[1], sys.argv[2]
urls = json.load(open("/tmp/phasec/urls.json"))
tokens = {"admin": open("/tmp/phasec/tok_mikexiao").read().strip(), "bob": open("/tmp/phasec/tok_bob").read().strip(), "anon": None}
HEADERS = ["content-type", "www-authenticate", "last-modified", "cache-control", "content-disposition"]


def fetch(path, who):
    req = urllib.request.Request(base + path)
    if tokens[who]:
        req.add_header("Authorization", "Bearer " + tokens[who])
    try:
        with urllib.request.urlopen(req, timeout=60) as r:
            status, hdrs, body = r.status, r.headers, r.read()
    except urllib.error.HTTPError as e:
        status, hdrs, body = e.code, e.headers, e.read()
    h = {k: hdrs.get(k) for k in HEADERS if hdrs.get(k) is not None}
    try:
        b = json.loads(body)
    except Exception:
        b = {"_raw_len": len(body), "_raw_head": body[:200].decode("latin1")}
    return status, h, b


def is_paged(b):
    return isinstance(b, dict) and "per_page" in b and "items" in b


COLS = ["id", "name", "slug", "createdAt", "created_at", "updatedAt", "updateAt", "groupId", "householdId", "username",
        "fullName", "email", "position", "title", "text", "date", "entryType", "day", "actionType", "url", "enabled",
        "color", "rating", "lastMade", "totalTime", "description", "nameNormalized", "pluralName", "abbreviation",
        "onHand", "subject", "eventType", "timestamp", "recipeId", "userId", "queryFilterString", "password", "admin",
        "name:asc", "name:up", "createdAt:asc,name", "name,id:desc", "random", "NAME", "UserId", "aB"]
VARIANTS = ["perPage=-1", "page=2&perPage=1", "orderBy=nope", "page=-1&perPage=1", "page=-1", "perPage=1",
            "perPage=1&queryFilter=x%3D1", "perPage=0", "page=abc", "perPage=x", "orderDirection=up",
            "orderDirection=asc", "orderByNullPosition=last&orderBy=name", "orderByNullPosition=sideways",
            "orderBy=random", "orderBy=random&paginationSeed=1", "search=a", "search=chicken", "search=%22red+curry%22",
            "search=caf%C3%A9", "search=a&orderBy=name", "search=a&perPage=1", "per_page=1", "order_by=name",
            "perPage=-1&page=2", "perPage=-2", "page=0", "perPage=1&foo=bar", "perPage=1&orderBy=name&orderDirection=asc"]

out = {}


def job(key, path, who):
    out[key] = fetch(path, who)


with ThreadPoolExecutor(4) as ex:
    for path in urls:
        for who in tokens:
            ex.submit(job, f"{who} {path}", path, who)
# second round: pagination variants for paged routes
paged = sorted({k.split(" ", 1)[1] for k, v in out.items() if is_paged(v[2]) and "?" not in k})
with ThreadPoolExecutor(4) as ex:
    for path in paged:
        for who in tokens:
            for v in VARIANTS:
                ex.submit(job, f"{who} {path}?{v}", f"{path}?{v}", who)
        for who in ["admin", "bob"]:
            for c in COLS:
                ex.submit(job, f"{who} {path}?perPage=3&orderBy={c}", f"{path}?perPage=3&orderBy={c}", who)
json.dump(out, open(outfile, "w"), indent=1, sort_keys=True, ensure_ascii=False)
print(len(out), "requests;", len(paged), "paged routes")

