"""uses.py FILE [+Use\\Name] [-Use\\Name] ... : edit the top-level use block, keep it sorted."""
import re, sys
path = sys.argv[1]
src = open(path).read()
lines = src.split("\n")
idx = [i for i, l in enumerate(lines) if re.match(r"^use [A-Z][\w\\]*;$", l)]
uses = {lines[i][4:-1] for i in idx}
for a in sys.argv[2:]:
    if a[0] == "+": uses.add(a[1:])
    else: uses.discard(a[1:])
if idx:
    start, end = idx[0], idx[-1]
    lines[start:end + 1] = ["use %s;" % u for u in sorted(uses, key=str.lower)]
else:
    ns = next(i for i, l in enumerate(lines) if l.startswith("namespace "))
    lines[ns + 1:ns + 1] = [""] + ["use %s;" % u for u in sorted(uses, key=str.lower)]
open(path, "w").write("\n".join(lines))
EOF
