"""wtest.py BASE OUT : write-route checks (auth, not-found, slugs) on rows created and deleted here."""
import json
import re
import sys
import urllib.error
import urllib.request

base, outfile = sys.argv[1], sys.argv[2]
routes = json.load(open("/tmp/phasec/routes.json"))
tok = {"admin": open("/tmp/phasec/tok_mikexiao").read().strip(), "bob": open("/tmp/phasec/tok_bob").read().strip(), "anon": None}
BOGUS = "3fa85f64-5717-4562-b3fc-2c963f66afa6"
out = []


def call(who, method, path, body=None):
    data = None if body is None else json.dumps(body).encode()
    req = urllib.request.Request(base + path, method=method, data=data)
    if tok[who]:
        req.add_header("Authorization", "Bearer " + tok[who])
    req.add_header("Content-Type", "application/json")
    try:
        with urllib.request.urlopen(req, timeout=60) as r:
            s, raw, h = r.status, r.read(), r.headers
    except urllib.error.HTTPError as e:
        s, raw, h = e.code, e.read(), e.headers
    try:
        b = json.loads(raw) if raw else None
    except Exception:
        b = raw[:200].decode("latin1")
    return s, b, h.get("www-authenticate")


def norm(x):
    s = json.dumps(x, sort_keys=True, ensure_ascii=False)
    ids = {}
    s = re.sub(r"[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}", lambda m: ids.setdefault(m.group(0), f"<id{len(ids)}>") if m.group(0) != BOGUS else "<bogus>", s)
    s = re.sub(r"\d{4}-\d\d-\d\dT\d\d:\d\d:\d\d(\.\d+)?(Z|\+00:00)?", "<ts>", s)
