docker exec mealie-w5-php bash -lc 'cd /tmp/phasec && python3 - <<EOF
import json, re
a=json.load(open("w_old.json")); b=json.load(open("w_new.json"))
U=r"[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}"
def flat(o, p=""):
    if isinstance(o, dict):
        for k,v in o.items(): yield from flat(v, p+"."+k)
    elif isinstance(o, list):
        for i,v in enumerate(o): yield from flat(v, p+f"[{i}]")
    else: yield p, o
for x,y in zip(a,b):
    if x[0]=="auth-body": continue
    px, py = re.sub(U,"<id>",x[3]), re.sub(U,"<id>",y[3])
    if [x[0],x[2],px,x[4],x[5],x[6]] != [y[0],y[2],py,y[4],y[5],y[6]]:
        fx, fy = dict(flat(x[5])), dict(flat(y[5]))
        d = {k:(fx.get(k), fy.get(k)) for k in set(fx)|set(fy) if fx.get(k)!=fy.get(k)}
        print(x[0], x[2], px, x[4], y[4], d)
EOF'

